            case '|':
            case '\\':
                replacement = "\\" + match_str;
                break;
            case '^':
            case '_':
                replacement = "\\" + match_str;
                break;
            case '\\':
                replacement = "\\\\" + match_str;
                break;
            default:
                replacement = "</" + match_str;
                break;
        }
        return replacement;
    };

    // Use a lambda function to replace all Markdown list items with HTML list items
    auto convert_list_item = [](const std::string& match_str) {
        std::string replacement = "<li>";
        if (match_str[0] == '1') {
            replacement += match_str;
        } else {
            replacement += 1 + match_str.substr(1).length();
        }
        replacement += "</li>";
        return replacement;
    };

    // Use a lambda function to replace all Markdown blockquotes with HTML blockquotes
    auto convert_blockquote = [](const std::string& match_str) {
        std::string replacement = "<blockquote>";
        replacement += match_str.substr(1, match_str.length() - 3);
        replacement += "</blockquote>";
        return replacement;
    };

    // Replace all Markdown syntax characters with their HTML equivalent
    auto markdown_to_html = std::regex_replace(markdown, markdown_syntex, markdown_to_html_converter);

    // Replace all Markdown list items with HTML list items
    auto list_item_match = std::regex_match(markdown, std::regex("^\\s*(\\d+)\\s*\\*"));
    if (list_item_match) {
        auto list_item = list_item_match[1];
        markdown_to_html = std::regex_replace(markdown_to_html, std::regex("<([a-z]+)>(\\d+)\\s*\\*"), convert_list_item, std::regex_constants::optimization);
    }

    // Replace all Markdown blockquotes with HTML blockquotes
    auto blockquote_match = std::regex_match(markdown, std::regex("^\\s*\\*\\s+(.+)$"));
    if (blockquote_match) {
        auto blockquote = blockquote_match[1];
        markdown_to_html = std::regex_replace(markdown_to_html, std::regex("^\\s*\\*\\s+([^\\*]+)$"), convert_blockquote);
    }

    // Replace any remaining Markdown syntax characters with their HTML equivalent
    auto html_replacement = std::regex_replace(markdown_to_html, html_syntax, "<$1>");
    return html_replacement;
}
