        if (file.is_open()) {
            std::cout << "Counting the occurrences of the word '" << word << "' in the text file..." << std::endl;

            int word_count = 0;
            std::string line;
            while (std::getline(file, line)) {
                // Remove any leading or trailing spaces from the line
                line.erase(line.begin(), std::find_if(line.begin(), line.end(), [](int ch) { return !isspace(ch); }));
                line.erase(std::find_if(line.rbegin(), line.rend(), [](int ch) { return !isspace(ch); }).base(), line.end());

                // Use a standard library `regex` function to count occurrences of the word in each line
                word_count += std::count(std::begin(line), std::end(line), ' ' + word + ' ');
            }

            file.close();

            std::cout << "The word '" << word << "' occurred " << word_count << " times in the text file." << std::endl;
        } else {
            std::cerr << "Error opening the text file." << std::endl;
        }

        return 0;
    }

